/**
 * TenantRentPayments
 *
 * Manager-side view of a tenant's invoice history. Payments are
 * auto-generated by the server scheduler (monthly on the 1st).
 *
 * Manager actions available here:
 *  - Record cash / bank-transfer / cheque / M-Pesa payments manually
 *  - Send a payment reminder
 *  - Apply a late fee to an overdue invoice
 *  - Delete an invoice
 *  - Export payment history to CSV
 *  - Download a plain-text receipt
 *
 * M-Pesa STK push is intentionally NOT available here.
 * An STK push asks a customer to authorise money leaving their own
 * account — it must be initiated by the account holder (the tenant),
 * not by a third party. Tenants initiate M-Pesa payments themselves
 * from the Tenant Portal → Payments tab.
 */
import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@/components/ui/select';
import {
  Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle,
} from '@/components/ui/dialog';
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem,
  DropdownMenuSeparator, DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Skeleton } from '@/components/ui/skeleton';
import {
  Building, Clock, CheckCircle, AlertTriangle,
  Download, Send, DollarSign, Calendar, FileText, Banknote,
  Receipt, MoreVertical, Mail, Phone, CreditCard, Loader2,
  RefreshCw, ChevronLeft, ChevronRight, Search, X,
} from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { apiRequest, ensureArray } from '@/lib/queryClient';
import { format } from 'date-fns';

// ── Types ─────────────────────────────────────────────────────────────────────

interface RentPayment {
  id: number;
  tenantId: number;
  invoiceNumber?: string;
  amount: string;
  currency: string;
  dueDate: string;
  paidDate?: string;
  paymentMethod?: string;
  mpesaTransactionId?: string;
  bankReference?: string;
  status: 'pending' | 'paid' | 'overdue' | 'partial';
  notes?: string;
  createdAt: string;
  updatedAt: string;
}

interface TenantRentPaymentsProps {
  tenantId: string;
  tenantName: string;
  tenantEmail?: string;
  tenantPhone?: string;
  monthlyRent?: number;
  currency?: string;
}

// ── Config ────────────────────────────────────────────────────────────────────

const STATUS_CONFIG = {
  pending: { label: 'Pending', cls: 'bg-amber-100 text-amber-800 border-amber-200 dark:bg-amber-950 dark:text-amber-400 dark:border-amber-800' },
  paid:    { label: 'Paid',    cls: 'bg-emerald-50 text-emerald-700 border border-emerald-200' },
  overdue: { label: 'Overdue', cls: 'bg-red-100 text-red-800 border-red-200 dark:bg-red-950 dark:text-red-400 dark:border-red-800' },
  partial: { label: 'Partial', cls: 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-950 dark:text-blue-400 dark:border-blue-800' },
};

const METHOD_CONFIG: Record<string, { label: string; icon: typeof CreditCard; color: string }> = {
  cash:          { label: 'Cash',          icon: Banknote,   color: 'text-green-600'  },
  bank_transfer: { label: 'Bank Transfer', icon: Building,   color: 'text-blue-600'   },
  cheque:        { label: 'Cheque',        icon: FileText,   color: 'text-purple-600' },
  mpesa:         { label: 'M-Pesa',        icon: CreditCard, color: 'text-green-600'  },
  online:        { label: 'Online',        icon: CreditCard, color: 'text-blue-600'   },
};

const PAGE_SIZES = [10, 25, 50];
const fmt     = (n: string | number, cur = 'KES') =>
  `${cur} ${Number(n).toLocaleString('en-KE', { minimumFractionDigits: 2 })}`;
const fmtDate = (d?: string) => d ? format(new Date(d), 'dd MMM yyyy') : '—';

// ── Component ─────────────────────────────────────────────────────────────────

export default function TenantRentPayments({
  tenantId, tenantName, tenantEmail, tenantPhone, currency = 'KES',
}: TenantRentPaymentsProps) {
  const { toast } = useToast();
  const qc        = useQueryClient();
  const today     = format(new Date(), 'yyyy-MM-dd');

  const [filter,          setFilter]          = useState('all');
  const [search,          setSearch]          = useState('');
  const [page,            setPage]            = useState(1);
  const [pageSize,        setPageSize]        = useState(10);
  const [selectedPayment, setSelectedPayment] = useState<RentPayment | null>(null);
  const [markPaidOpen,    setMarkPaidOpen]    = useState(false);
  const [lateFeeOpen,     setLateFeeOpen]     = useState(false);
  const [lateFeePayment,  setLateFeePayment]  = useState<RentPayment | null>(null);
  const [lateFeeType,     setLateFeeType]     = useState<'percentage' | 'fixed'>('percentage');
  const [lateFeeValue,    setLateFeeValue]    = useState('');

  const { data: payments = [], isLoading } = useQuery<RentPayment[]>({
    queryKey: ['/api/rent-payments', { tenantId }],
    queryFn: async () =>
      ensureArray(await (await apiRequest(`/api/rent-payments?tenantId=${tenantId}`)).json()),
  });

  const paid    = payments.filter(p => p.status === 'paid');
  const pending = payments.filter(p => p.status === 'pending');
  const overdue = payments.filter(p => p.status === 'overdue');
  const totalCollected = paid.reduce((s, p)    => s + Number(p.amount), 0);
  const totalPending   = pending.reduce((s, p) => s + Number(p.amount), 0);
  const totalOverdue   = overdue.reduce((s, p) => s + Number(p.amount), 0);
  const onTimeRate     = payments.length ? Math.round((paid.length / payments.length) * 100) : 0;

  const filtered = payments.filter(p => {
    if (filter !== 'all' && p.status !== filter) return false;
    if (!search) return true;
    const q = search.toLowerCase();
    return (p.invoiceNumber ?? '').toLowerCase().includes(q) || p.status.includes(q);
  });
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const safePage   = Math.min(page, totalPages);
  const paged      = filtered.slice((safePage - 1) * pageSize, safePage * pageSize);

  const computedLateFee = lateFeePayment
    ? lateFeeType === 'percentage'
      ? parseFloat(lateFeePayment.amount) * (parseFloat(lateFeeValue || '0') / 100)
      : parseFloat(lateFeeValue || '0')
    : 0;

  // ── Mutations ─────────────────────────────────────────────────────────────

  const markPaidMutation = useMutation({
    mutationFn: ({ id, data }: { id: number; data: any }) =>
      apiRequest(`/api/rent-payments/${id}/mark-paid`, { method: 'POST', data }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['/api/rent-payments'] });
      setMarkPaidOpen(false);
      toast({ title: 'Payment recorded' });
    },
    onError: () => toast({ title: 'Failed to record payment', variant: 'destructive' }),
  });

  const reminderMutation = useMutation({
    mutationFn: (id: number) =>
      apiRequest(`/api/rent-payments/${id}/send-reminder`, { method: 'POST' }),
    onSuccess: () => toast({ title: 'Reminder sent' }),
    onError:   () => toast({ title: 'Failed to send reminder', variant: 'destructive' }),
  });

  const deleteMutation = useMutation({
    mutationFn: (id: number) =>
      apiRequest(`/api/rent-payments/${id}`, { method: 'DELETE' }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['/api/rent-payments'] }),
    onError:   () => toast({ title: 'Failed to delete invoice', variant: 'destructive' }),
  });

  const dedupMutation = useMutation({
    mutationFn: () =>
      apiRequest(`/api/rent-payments/dedup-cleanup`, { method: 'POST', data: { tenantId } }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['/api/rent-payments'] });
      toast({ title: 'Duplicates removed' });
    },
  });

  const lateFeeMutation = useMutation({
    mutationFn: ({ id, amount }: { id: number; amount: string }) =>
      apiRequest(`/api/rent-payments/${id}/apply-late-fee`, { method: 'POST', data: { amount } }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['/api/rent-payments'] });
      toast({ title: 'Late fee applied' });
    },
    onError: () => toast({ title: 'Failed to apply late fee', variant: 'destructive' }),
  });

  const openMarkPaid = (p: RentPayment) => { setSelectedPayment(p); setMarkPaidOpen(true); };
  const openLateFee  = (p: RentPayment) => { setLateFeePayment(p); setLateFeeValue(''); setLateFeeOpen(true); };

  // ── CSV export ────────────────────────────────────────────────────────────

  const handleExport = () => {
    const header = 'Invoice,Amount,Currency,Due Date,Paid Date,Method,Status,Notes';
    const rows = payments.map(p => [
      `"${p.invoiceNumber ?? `PAY-${p.id}`}"`,
      `"${p.amount}"`,
      `"${p.currency}"`,
      `"${p.dueDate}"`,
      `"${p.paidDate ?? ''}"`,
      `"${p.paymentMethod ?? ''}"`,
      `"${p.status}"`,
      `"${(p.notes ?? '').replace(/"/g, '""')}"`,
    ].join(',')).join('\n');
    const blob = new Blob([`${header}\n${rows}`], { type: 'text/csv' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url;
    a.download = `payments-${tenantName.replace(/\s+/g, '-')}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast({ title: 'Exported', description: `${payments.length} payment records downloaded` });
  };

  // ── Loading skeleton ──────────────────────────────────────────────────────

  if (isLoading) {
    return (
      <div className="space-y-4">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-20 rounded-2xl" />)}
        </div>
        <Skeleton className="h-64 rounded-2xl" />
      </div>
    );
  }

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-5">

      {/* ── KPI strip ────────────────────────────────────────────────────── */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {[
          { label: 'Collected', value: fmt(totalCollected, currency), sub: `${paid.length} paid`,    icon: <CheckCircle className="h-5 w-5 text-green-600" />,   bg: 'bg-green-50 dark:bg-green-950/40' },
          { label: 'Pending',   value: fmt(totalPending, currency),   sub: `${pending.length} invoice${pending.length !== 1 ? 's' : ''}`, icon: <Clock className="h-5 w-5 text-amber-600" />, bg: 'bg-amber-50 dark:bg-amber-950/40' },
          { label: 'Overdue',   value: fmt(totalOverdue, currency),   sub: `${overdue.length} unpaid`, icon: <AlertTriangle className="h-5 w-5 text-red-600" />, bg: 'bg-red-50 dark:bg-red-950/40' },
          { label: 'On-time',   value: `${onTimeRate}%`,              sub: `${payments.length} total`, icon: <Receipt className="h-5 w-5 text-blue-600" />,      bg: 'bg-blue-50 dark:bg-blue-950/40' },
        ].map(kpi => (
          <Card key={kpi.label} className="rounded-2xl shadow-none border-border dark:border-gray-800">
            <CardContent className="p-4 flex items-center gap-3">
              <div className={`p-2 rounded-lg ${kpi.bg} flex-shrink-0`}>{kpi.icon}</div>
              <div className="min-w-0">
                <p className="text-[11px] uppercase tracking-wide text-muted-foreground font-medium">{kpi.label}</p>
                <p className="text-base font-bold text-foreground truncate">{kpi.value}</p>
                <p className="text-[11px] text-muted-foreground">{kpi.sub}</p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* ── Invoice list ─────────────────────────────────────────────────── */}
      <Card className="rounded-2xl shadow-none border-border dark:border-gray-800">
        <CardHeader className="pb-3 pt-5 px-5 flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-sm font-semibold">Invoices</CardTitle>
            <CardDescription className="text-xs mt-0.5">
              Auto-generated monthly · record payment once received
            </CardDescription>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" className="h-8" onClick={handleExport}>
              <Download className="h-3.5 w-3.5 mr-1.5" />Export
            </Button>
            {/* Dedup button — shown when same due-date appears more than once */}
            {(() => {
              const dueDates = payments.filter(p => p.status !== 'paid').map(p => p.dueDate);
              return dueDates.length !== new Set(dueDates).size ? (
                <Button
                  variant="outline"
                  size="sm"
                  className="h-8 text-amber-600 border-amber-300 hover:bg-amber-50"
                  disabled={dedupMutation.isPending}
                  onClick={() => dedupMutation.mutate()}
                  title="Remove duplicate invoices for the same month"
                >
                  {dedupMutation.isPending
                    ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    : <RefreshCw className="h-3.5 w-3.5 mr-1.5" />}
                  Fix duplicates
                </Button>
              ) : null;
            })()}
            {tenantEmail && (
              <Button variant="outline" size="sm" className="h-8" onClick={() => window.open(`mailto:${tenantEmail}`)}>
                <Mail className="h-3.5 w-3.5" />
              </Button>
            )}
            {tenantPhone && (
              <Button variant="outline" size="sm" className="h-8" onClick={() => window.open(`tel:${tenantPhone}`)}>
                <Phone className="h-3.5 w-3.5" />
              </Button>
            )}
          </div>
        </CardHeader>

        <CardContent className="px-5 pb-5">
          {/* Toolbar */}
          <div className="flex items-center gap-2 flex-wrap mb-4">
            <div className="relative flex-1 min-w-0 max-w-xs">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
              <Input
                value={search}
                onChange={e => { setSearch(e.target.value); setPage(1); }}
                placeholder="Search invoices…"
                className="pl-8 h-8 text-sm border-border dark:border-gray-700"
              />
              {search && (
                <button className="absolute right-2.5 top-1/2 -translate-y-1/2" onClick={() => { setSearch(''); setPage(1); }}>
                  <X className="h-3.5 w-3.5 text-muted-foreground hover:text-foreground" />
                </button>
              )}
            </div>

            <Select value={filter} onValueChange={v => { setFilter(v); setPage(1); }}>
              <SelectTrigger className="w-28 h-8 text-sm border-border dark:border-gray-700">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
                <SelectItem value="overdue">Overdue</SelectItem>
                <SelectItem value="paid">Paid</SelectItem>
                <SelectItem value="partial">Partial</SelectItem>
              </SelectContent>
            </Select>

            <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
              <span>Show</span>
              <Select value={String(pageSize)} onValueChange={v => { setPageSize(Number(v)); setPage(1); }}>
                <SelectTrigger className="w-16 h-8 text-sm border-border dark:border-gray-700">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {PAGE_SIZES.map(n => <SelectItem key={n} value={String(n)}>{n}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <span className="text-xs text-muted-foreground ml-auto">
              {filtered.length} result{filtered.length !== 1 ? 's' : ''}
            </span>
          </div>

          {/* Empty state */}
          {payments.length === 0 ? (
            <div className="text-center py-12">
              <div className="inline-flex p-4 bg-muted rounded-full mb-4">
                <RefreshCw className="h-8 w-8 text-muted-foreground" />
              </div>
              <h3 className="text-sm font-semibold text-foreground mb-1">No invoices yet</h3>
              <p className="text-xs text-muted-foreground max-w-xs mx-auto">
                The scheduler automatically generates monthly rent invoices for active tenants on the
                1st of each month. Check back tomorrow, or ensure the tenant's monthly rent and lease
                dates are set.
              </p>
            </div>
          ) : filtered.length === 0 ? (
            <div className="text-center py-8">
              <p className="text-sm text-muted-foreground">No invoices match your filters.</p>
              <button
                className="text-xs text-blue-600 mt-1 hover:underline"
                onClick={() => { setSearch(''); setFilter('all'); }}
              >
                Clear filters
              </button>
            </div>
          ) : (
            <>
              <div className="space-y-2">
                {paged.map(payment => {
                  const MethodIcon  = METHOD_CONFIG[payment.paymentMethod ?? '']?.icon ?? CreditCard;
                  const methodColor = METHOD_CONFIG[payment.paymentMethod ?? '']?.color ?? 'text-muted-foreground';
                  const statusCls   = STATUS_CONFIG[payment.status]?.cls ?? '';
                  const isPaid      = payment.status === 'paid';
                  const isActionable = !isPaid;
                  const daysOverdue = !isPaid && payment.dueDate < today
                    ? Math.floor((Date.now() - new Date(payment.dueDate).getTime()) / 86400000)
                    : 0;

                  return (
                    <div
                      key={payment.id}
                      className={`flex items-center gap-3 rounded-xl border px-4 py-3 ${
                        payment.status === 'overdue' || (payment.status === 'pending' && payment.dueDate < today)
                          ? 'border-red-200 dark:border-red-800 bg-red-50/40 dark:bg-red-950/20'
                          : 'border-border dark:border-gray-800'
                      }`}
                    >
                      {/* Invoice info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-0.5">
                          <span className="text-xs font-mono text-muted-foreground">
                            {payment.invoiceNumber ?? `PAY-${payment.id}`}
                          </span>
                          <Badge variant="outline" className={`text-[10px] px-1.5 py-0 ${statusCls}`}>
                            {STATUS_CONFIG[payment.status]?.label ?? payment.status}
                          </Badge>
                          {daysOverdue > 0 && (
                            <span className="text-[10px] text-red-600 font-semibold">{daysOverdue}d overdue</span>
                          )}
                        </div>
                        <div className="flex items-center gap-3 text-xs text-muted-foreground">
                          <span className="font-semibold text-sm text-foreground">
                            {fmt(payment.amount, currency)}
                          </span>
                          <span className="flex items-center gap-1">
                            <Calendar className="h-3 w-3" />Due {fmtDate(payment.dueDate)}
                          </span>
                          {isPaid && payment.paidDate && (
                            <span className="flex items-center gap-1 text-green-600">
                              <CheckCircle className="h-3 w-3" />Paid {fmtDate(payment.paidDate)}
                            </span>
                          )}
                          {isPaid && payment.paymentMethod && (
                            <span className={`flex items-center gap-1 ${methodColor}`}>
                              <MethodIcon className="h-3 w-3" />
                              {METHOD_CONFIG[payment.paymentMethod]?.label ?? payment.paymentMethod}
                            </span>
                          )}
                        </div>
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-1.5 flex-shrink-0">
                        {isActionable && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="h-8 text-xs"
                            onClick={() => openMarkPaid(payment)}
                          >
                            <DollarSign className="h-3.5 w-3.5 mr-1" />Record
                          </Button>
                        )}

                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" className="w-48">
                            {isActionable && (
                              <DropdownMenuItem onClick={() => reminderMutation.mutate(payment.id)}>
                                <Send className="h-4 w-4 mr-2 text-green-600" />Send reminder
                              </DropdownMenuItem>
                            )}
                            {isActionable && payment.dueDate < today && (
                              <DropdownMenuItem
                                className="text-amber-600"
                                onClick={() => openLateFee(payment)}
                              >
                                <AlertTriangle className="h-4 w-4 mr-2" />Apply late fee…
                              </DropdownMenuItem>
                            )}
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              className="text-red-600"
                              onClick={() => {
                                if (confirm(`Delete ${payment.invoiceNumber ?? `PAY-${payment.id}`}? This cannot be undone.`)) {
                                  deleteMutation.mutate(payment.id);
                                }
                              }}
                            >
                              <X className="h-4 w-4 mr-2" />Delete invoice
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => {
                              const lines = [
                                `RENT RECEIPT — ${tenantName}`,
                                `Invoice: ${payment.invoiceNumber ?? `PAY-${payment.id}`}`,
                                `Amount:  ${fmt(payment.amount, currency)}`,
                                `Due:     ${fmtDate(payment.dueDate)}`,
                                `Status:  ${payment.status}`,
                                payment.paidDate           ? `Paid:    ${fmtDate(payment.paidDate)}`    : '',
                                payment.paymentMethod      ? `Method:  ${payment.paymentMethod}`        : '',
                                payment.mpesaTransactionId ? `M-Pesa:  ${payment.mpesaTransactionId}`  : '',
                                payment.notes              ? `Notes:   ${payment.notes}`                : '',
                              ].filter(Boolean).join('\n');
                              const blob = new Blob([lines], { type: 'text/plain' });
                              const a = document.createElement('a');
                              a.href = URL.createObjectURL(blob);
                              a.download = `receipt-${payment.invoiceNumber ?? payment.id}.txt`;
                              a.click();
                            }}>
                              <Download className="h-4 w-4 mr-2" />Download receipt
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-between mt-4">
                  <p className="text-xs text-muted-foreground">
                    {(safePage - 1) * pageSize + 1}–{Math.min(safePage * pageSize, filtered.length)} of {filtered.length}
                  </p>
                  <div className="flex items-center gap-1">
                    <Button variant="outline" size="sm" className="h-7 w-7 p-0" disabled={safePage === 1} onClick={() => setPage(p => p - 1)}>
                      <ChevronLeft className="h-3.5 w-3.5" />
                    </Button>
                    {Array.from({ length: totalPages }, (_, i) => i + 1)
                      .filter(n => n === 1 || n === totalPages || Math.abs(n - safePage) <= 1)
                      .reduce<(number | '…')[]>((acc, n, i, arr) => {
                        if (i > 0 && n - (arr[i - 1] as number) > 1) acc.push('…');
                        acc.push(n);
                        return acc;
                      }, [])
                      .map((n, i) => n === '…'
                        ? <span key={`e${i}`} className="px-1 text-muted-foreground text-xs">…</span>
                        : <Button key={n} variant={n === safePage ? 'default' : 'outline'} size="sm" className="h-7 w-7 p-0 text-xs" onClick={() => setPage(n as number)}>{n}</Button>
                      )}
                    <Button variant="outline" size="sm" className="h-7 w-7 p-0" disabled={safePage === totalPages} onClick={() => setPage(p => p + 1)}>
                      <ChevronRight className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* ── Record payment dialog ─────────────────────────────────────────── */}
      <Dialog open={markPaidOpen} onOpenChange={setMarkPaidOpen}>
        <DialogContent className="sm:max-w-sm rounded-2xl">
          <DialogHeader>
            <DialogTitle>Record Payment</DialogTitle>
            <DialogDescription>
              Manually record a payment received for{' '}
              <span className="font-medium">
                {selectedPayment?.invoiceNumber ?? `Invoice #${selectedPayment?.id}`}
              </span>
              {' '}({selectedPayment ? fmt(selectedPayment.amount, currency) : ''})
            </DialogDescription>
          </DialogHeader>

          <form
            onSubmit={e => {
              e.preventDefault();
              if (!selectedPayment) return;
              const fd = new FormData(e.currentTarget);
              markPaidMutation.mutate({
                id: selectedPayment.id,
                data: {
                  paidDate:      fd.get('paidDate'),
                  paymentMethod: fd.get('method'),
                  transactionId: fd.get('transactionId') || undefined,
                  bankReference: fd.get('bankReference') || undefined,
                  notes:         fd.get('notes')         || undefined,
                },
              });
            }}
            className="space-y-4 mt-2"
          >
            <div className="space-y-1.5">
              <Label className="text-xs">Payment Date</Label>
              <Input name="paidDate" type="date" defaultValue={today} required className="h-9" />
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs">Payment Method</Label>
              <Select name="method" defaultValue="cash" required>
                <SelectTrigger className="h-9"><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="cash">Cash</SelectItem>
                  <SelectItem value="bank_transfer">Bank Transfer</SelectItem>
                  <SelectItem value="cheque">Cheque</SelectItem>
                  <SelectItem value="mpesa">M-Pesa (enter transaction ID below)</SelectItem>
                  <SelectItem value="online">Online</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs">Transaction / Reference (optional)</Label>
              <Input name="transactionId" placeholder="e.g. QHJ7XKABCD or CHQ-001" className="h-9" />
            </div>

            <div className="space-y-1.5">
              <Label className="text-xs">Notes (optional)</Label>
              <Textarea name="notes" rows={2} placeholder="Any relevant notes…" />
            </div>

            <div className="flex gap-2 justify-end">
              <Button type="button" variant="outline" size="sm" onClick={() => setMarkPaidOpen(false)}>
                Cancel
              </Button>
              <Button
                type="submit"
                size="sm"
                disabled={markPaidMutation.isPending}
                className="bg-blue-600 hover:bg-blue-700 text-white"
              >
                {markPaidMutation.isPending && <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />}
                Record Payment
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>

      {/* ── Late fee dialog ───────────────────────────────────────────────── */}
      <Dialog open={lateFeeOpen} onOpenChange={open => { if (!open) setLateFeeOpen(false); }}>
        <DialogContent className="sm:max-w-sm rounded-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-amber-500" />Apply Late Fee
            </DialogTitle>
            <DialogDescription>
              {lateFeePayment && (
                <>
                  Adding a late fee to{' '}
                  <span className="font-medium">
                    {lateFeePayment.invoiceNumber ?? `PAY-${lateFeePayment.id}`}
                  </span>{' '}
                  ({fmt(lateFeePayment.amount, currency)})
                </>
              )}
            </DialogDescription>
          </DialogHeader>

          {lateFeePayment && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-2">
                {(['percentage', 'fixed'] as const).map(type => (
                  <button
                    key={type}
                    type="button"
                    onClick={() => setLateFeeType(type)}
                    className={`rounded-xl border-2 px-4 py-3 text-sm font-medium transition-colors ${
                      lateFeeType === type
                        ? 'border-blue-600 bg-blue-50 dark:bg-blue-950/40 text-blue-700 dark:text-blue-400'
                        : 'border-border text-muted-foreground hover:bg-muted/50'
                    }`}
                  >
                    <div className="text-lg font-bold mb-0.5">
                      {type === 'percentage' ? '%' : currency}
                    </div>
                    {type === 'percentage' ? 'Percentage' : 'Fixed amount'}
                  </button>
                ))}
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs">
                  {lateFeeType === 'percentage' ? 'Percentage (%)' : `Fixed amount (${currency})`}
                </Label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground font-medium">
                    {lateFeeType === 'percentage' ? '%' : currency}
                  </span>
                  <Input
                    type="number"
                    min="0"
                    step={lateFeeType === 'percentage' ? '0.1' : '1'}
                    placeholder={lateFeeType === 'percentage' ? 'e.g. 5' : 'e.g. 1500'}
                    value={lateFeeValue}
                    onChange={e => setLateFeeValue(e.target.value)}
                    className="pl-10 h-9"
                    autoFocus
                  />
                </div>
              </div>

              {computedLateFee > 0 && (
                <div className="rounded-xl bg-muted/50 dark:bg-gray-800/50 px-4 py-3 space-y-1.5 text-sm">
                  <div className="flex justify-between text-muted-foreground">
                    <span>Original amount</span>
                    <span>{fmt(lateFeePayment.amount, currency)}</span>
                  </div>
                  <div className="flex justify-between text-amber-600 dark:text-amber-400">
                    <span>Late fee{lateFeeType === 'percentage' ? ` (${lateFeeValue}%)` : ''}</span>
                    <span>+ {fmt(computedLateFee, currency)}</span>
                  </div>
                  <div className="flex justify-between font-bold text-foreground border-t border-border pt-1.5">
                    <span>New total</span>
                    <span>{fmt(parseFloat(lateFeePayment.amount) + computedLateFee, currency)}</span>
                  </div>
                </div>
              )}

              <div className="flex gap-2 justify-end">
                <Button variant="outline" size="sm" onClick={() => setLateFeeOpen(false)}>Cancel</Button>
                <Button
                  size="sm"
                  disabled={computedLateFee <= 0 || lateFeeMutation.isPending}
                  className="bg-amber-600 hover:bg-amber-700 text-white"
                  onClick={() =>
                    lateFeeMutation.mutate(
                      { id: lateFeePayment.id, amount: computedLateFee.toFixed(2) },
                      { onSuccess: () => setLateFeeOpen(false) },
                    )
                  }
                >
                  {lateFeeMutation.isPending && <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />}
                  Apply {computedLateFee > 0 ? fmt(computedLateFee, currency) : ''} fee
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>

    </div>
  );
}
